// App Store Connect → Users and Access → Integrations → API Keys
// Create a key (name, access role) → download .p8 file (SAVE — can't re-download)
// Note: KEY_ID (10 chars), ISSUER_ID (UUID).

// Store as CI secrets:
//   ASC_API_KEY_ID       = ABC123DEF4
//   ASC_API_ISSUER_ID    = 00000000-0000-0000-0000-000000000000
//   ASC_API_KEY_CONTENT  = base64-encoded .p8

// In Fastfile:
app_store_connect_api_key(
  key_id: ENV['ASC_API_KEY_ID'],
  issuer_id: ENV['ASC_API_ISSUER_ID'],
  key_content: ENV['ASC_API_KEY_CONTENT'],
  is_key_content_base64: true,
)

// Now pilot, deliver, match all use the API key — no Apple ID prompts + no 2FA.
